BEGIN TRANSACTION READ ONLY; SELECT jsonb_build_object('observedAt',clock_timestamp(),'readOnly',current_setting('transaction_read_only'),'draftCreateRpc',to_regprocedure('public.create_catalog_calculator_with_audit(text,text,text,text,text,jsonb)')::text,'bulkPrepareRpc',to_regprocedure('public.prepare_catalog_inventory_drafts(jsonb)')::text,'bulkJobPolicies',(SELECT jsonb_agg(jsonb_build_object('name',policyname,'command',cmd,'roles',roles,'using',qual,'check',with_check)) FROM pg_policies WHERE schemaname='public' AND tablename='calculator_bulk_jobs'),'governedLifecycleCounts',(SELECT jsonb_object_agg(lifecycle,n) FROM (SELECT lifecycle,count(*) n FROM public.calculator_catalog_admin GROUP BY lifecycle) s),'publicationManifestDefinition',(SELECT pg_get_functiondef(to_regprocedure('public.list_published_calculator_manifest()')))) AS evidence; COMMIT;
